import {caseInfo} from './workshop-content.mjs';
import {required,sampleTimes,correctDiagnosis,snapshot,faultModes} from './workshop-model.mjs';
import {adaptivePlan} from './workshop-adaptive.mjs';
export const examKey='mecanica.workshop.exam.v1';
export const examArchiveKey='mecanica.workshop.examArchive.v1';
export function newExam(results,random=Math.random){return {id:crypto.randomUUID(),started:new Date().toISOString(),finished:null,index:0,cases:Object.keys(required).map(kind=>({kind,fault:adaptivePlan(results,kind,random()).fault,readings:[],diagnosis:'',submitted:false}))};}
export function expected(c,id,time){const a=snapshot({...c,time}),b=snapshot({...c,time},true);return ({battery:['loaded'],ground:['drop'],input:['inputPeak','gain'],output:['outputPeak','clipped'],speed:['speed'],flow:['inlet'],leak:['leak'],supply:['supply'],exhaust:['back']})[id].some(k=>a[k]!==b[k]);}
export function examReady(c){return Boolean(c.diagnosis)&&required[c.kind].every(id=>sampleTimes(c).every(time=>c.readings.some(r=>r.id===id&&r.time===time&&typeof r.choice==='boolean')));}
export function grade(c){const readings=c.readings.map(r=>({...r,correct:r.choice===expected(c,r.id,r.time)}));const diagnosis=c.diagnosis===correctDiagnosis(c);return {readings,diagnosis,score:Math.round(50*readings.filter(r=>r.correct).length/Math.max(1,readings.length)+(diagnosis?50:0))};}
export function submit(exam){const c=exam.cases[exam.index];if(exam.finished||c.submitted||!examReady(c))return false;c.submitted=true;if(exam.retryOf){exam.finished=new Date().toISOString();return true;}if(exam.index<3)exam.index++;else exam.finished=new Date().toISOString();return true;}
export function validExam(x){return x&&(!x.retryOf||(typeof x.retryOf==='string'&&Number.isInteger(x.retryIndex)&&x.retryIndex>=0&&x.retryIndex<4&&x.index===x.retryIndex))&&typeof x.id==='string'&&Number.isInteger(x.index)&&x.index>=0&&x.index<4&&Array.isArray(x.cases)&&x.cases.length===4&&x.cases.every((c,i)=>c.kind===Object.keys(required)[i]&&faultModes.includes(c.fault)&&Array.isArray(c.readings)&&c.readings.every(r=>required[c.kind].includes(r.id)&&sampleTimes(c).includes(r.time)&&(typeof r.choice==='boolean'||r.choice===null))&&typeof c.diagnosis==='string'&&(c.diagnosis===''||Object.hasOwn(caseInfo[c.kind].options,c.diagnosis)||faultModes.map(fault=>correctDiagnosis({kind:c.kind,fault})).includes(c.diagnosis)));}
export function readExam(storage){try{const e=JSON.parse(storage.getItem(examKey));return validExam(e)?e:null;}catch{return null;}}
export function archiveExam(storage,exam){if(exam.retryOf||!exam.finished||!exam.cases.every(c=>c.submitted&&examReady(c)))return;let rows=[];try{rows=JSON.parse(storage.getItem(examArchiveKey)||'[]');if(!Array.isArray(rows))rows=[];}catch{}rows=rows.filter(validExam);if(!rows.some(e=>e.id===exam.id))rows.push(exam);storage.setItem(examArchiveKey,JSON.stringify(rows.slice(-25)));}
export function examEvidence(storage){try{const rows=JSON.parse(storage.getItem(examArchiveKey)||'[]');let retries=[];try{retries=JSON.parse(storage.getItem('mecanica.workshop.examRetries.v1')||'[]');if(!Array.isArray(retries))retries=[];}catch{}return Array.isArray(rows)?[...rows,...retries.filter(e=>e.retryOf&&Number.isInteger(e.retryIndex)&&e.retryIndex>=0&&e.retryIndex<4)].filter(e=>validExam(e)&&e.finished&&e.cases.every(c=>c.submitted&&examReady(c))).flatMap(e=>e.cases.filter((c,i)=>!e.retryOf||i===e.retryIndex).map(c=>{const g=grade(c);return {id:e.id+':'+c.kind,kind:c.kind,fault:c.fault,date:e.finished,score:g.score,hints:0,wrongDiagnosis:g.diagnosis?0:1,readings:g.readings,source:'exam'};})):[];}catch{return [];}}
